fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    let len = list.len();
    let first_part = &list[n..len]; // Elements from index n to the end
    let second_part = &list[0..n];   // Elements from the start to index n (exclusive)
    
    // Concatenate the two parts into a new vector
    let mut new_list = first_part.to_vec(); // Start with the first part
    new_list.extend_from_slice(second_part); // Append the second part
    
    new_list
}